RANKS = [
    (0, "Новичок"),
    (100, "Стажёр"),
    (300, "Оператор"),
    (600, "Специалист"),
    (1000, "Старший специалист"),
    (1500, "Эксперт"),
    (2200, "Мастер"),
    (3000, "Легенда культа"),
]


def get_agent_rank(xp: int) -> str:
    rank = "Новичок"
    for threshold, name in RANKS:
        if xp >= threshold:
            rank = name
    return rank


